@startuml

class User {
  + id : int
  + name : string
  + address : string
  + birthday : date
}

abstract class Role {}
interface BusinessOwner extends Role {}
interface HungryCustomer extends Role {}
interface Entertainer extends Role {}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + id : int
  + orderDateAndTime : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder extends Order {
  + entertainmentType : string
  + duration : time
}

class EntertainerAvailability {
  + day : string
  + available : boolean
}

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
HungryCustomer "0..*" Order : makes
Order "1" -- "1..*" Pizza : contains
Entertainer "1" -- "1" EntertainmentOrder : fulfills
Entertainer "1" -- "*" PizzaRestaurant : worksAt
PizzaRestaurant "1" -- "*" EntertainerAvailability : has

@enduml

